// D1 schema. Conventions:
// - Money is integer minor units in the row's currency (ISO 4217 exponent).
// - Business dates are ISO text (YYYY-MM-DD) in the workspace timezone.
// - Timestamps are integer milliseconds since the Unix epoch (UTC).
// - IDs are random UUID text, generated by the app.
// - FX rates are decimal strings plus an integer scaled by RATE_SCALE (src/shared/money/fx.ts).
// - Quantities are decimal strings with up to 3 decimals.
// Generate migrations with `pnpm db:generate` after any change here.
import { sql } from "drizzle-orm";
import {
  check,
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";
import {
  CUSTOM_FIELD_SCOPES,
  CUSTOM_FIELD_TYPES,
  DEFAULT_REMINDER_SCHEDULE,
  DISCOUNT_TYPES,
  DOCUMENT_KINDS,
  DOCUMENT_STATUSES,
  EMAIL_KINDS,
  EMAIL_STATUSES,
  FX_PROVIDERS,
  INVOICE_STATUSES,
  JOB_STATUSES,
  OVERDUE_REMINDER_CAP,
  PAYMENT_KINDS,
  QUOTE_STATUSES,
  RECURRING_FREQUENCIES,
  RECURRING_STATUSES,
  REMINDER_MODE_SETTINGS,
  REMINDER_MODES,
  type ReminderStep,
  SEND_MODE_SETTINGS,
  SEND_MODES,
  TEMPLATE_LAYOUTS,
  TEMPLATE_SECTIONS,
  type TemplateConfig,
  TRIGGERS,
  USER_ROLES,
} from "../../shared/domain";

const id = () =>
  text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID());

const nowMs = sql`(cast(unixepoch('subsec') * 1000 as integer))`;
const createdAt = () => integer("created_at").notNull().default(nowMs);
const updatedAt = () =>
  integer("updated_at")
    .notNull()
    .default(nowMs)
    .$onUpdateFn(() => Date.now());

const bool = (name: string) => integer(name, { mode: "boolean" });

const inList = (values: readonly string[]) => sql.raw(values.map((v) => `'${v}'`).join(", "));
// CHECK and partial-index SQL uses bare column names. Table-qualified names break when
// drizzle-kit later rebuilds a table under a temporary name.

// ---------------------------------------------------------------------------
// Workspace, team, and settings
// ---------------------------------------------------------------------------

/** Exactly one row (id = 1). Holds workspace defaults and the brand kit. */
export const workspace = sqliteTable(
  "workspace",
  {
    id: integer("id").primaryKey().default(1),
    name: text("name").notNull().default("My agency"),
    homeCurrency: text("home_currency").notNull().default("BDT"),
    timezone: text("timezone").notNull().default("Asia/Dhaka"),
    invoicePrefix: text("invoice_prefix").notNull().default("INV-"),
    quotePrefix: text("quote_prefix").notNull().default("Q-"),
    numberPadding: integer("number_padding").notNull().default(4),
    defaultPaymentTermsDays: integer("default_payment_terms_days").notNull().default(14),
    defaultQuoteValidityDays: integer("default_quote_validity_days").notNull().default(30),
    defaultTemplateId: text("default_template_id"),
    defaultTaxRateId: text("default_tax_rate_id"),
    reminderMode: text("reminder_mode", { enum: REMINDER_MODES }).notNull().default("suggest"),
    recurringSendMode: text("recurring_send_mode", { enum: SEND_MODES }).notNull().default("draft"),
    reminderSchedule: text("reminder_schedule", { mode: "json" })
      .$type<ReminderStep[]>()
      .notNull()
      .default(DEFAULT_REMINDER_SCHEDULE),
    overdueReminderCap: integer("overdue_reminder_cap").notNull().default(OVERDUE_REMINDER_CAP),
    // Brand kit
    businessName: text("business_name"),
    logoKey: text("logo_key"),
    accentColor: text("accent_color").notNull().default("#1f5a4e"),
    font: text("font").notNull().default("instrument-sans"),
    address: text("address"),
    taxId: text("tax_id"),
    bankDetails: text("bank_details"),
    footerText: text("footer_text"),
    emailFromName: text("email_from_name"),
    /** The verified Resend sender address, for example "billing@studio.example". */
    emailFromAddress: text("email_from_address"),
    replyToEmail: text("reply_to_email"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  () => [check("workspace_singleton", sql`id = 1`)],
);

/** Team list. Emails are stored lowercase. */
export const users = sqliteTable("users", {
  id: id(),
  email: text("email").notNull().unique(),
  name: text("name"),
  role: text("role", { enum: USER_ROLES }).notNull().default("member"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const taxRates = sqliteTable("tax_rates", {
  id: id(),
  name: text("name").notNull(),
  /** Percent as a decimal string, for example "15" or "7.5". */
  rate: text("rate").notNull(),
  /** Printed on documents that use this rate, for example "Reverse charge". */
  note: text("note"),
  archivedAt: integer("archived_at"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const templates = sqliteTable("templates", {
  id: id(),
  name: text("name").notNull(),
  layout: text("layout", { enum: TEMPLATE_LAYOUTS }).notNull(),
  config: text("config", { mode: "json" }).$type<TemplateConfig>().notNull(),
  archivedAt: integer("archived_at"),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const customFieldDefs = sqliteTable("custom_field_defs", {
  id: id(),
  label: text("label").notNull(),
  type: text("type", { enum: CUSTOM_FIELD_TYPES }).notNull(),
  /** The level where values are entered. */
  scope: text("scope", { enum: CUSTOM_FIELD_SCOPES }).notNull(),
  /** The template section where the field prints. */
  section: text("section", { enum: TEMPLATE_SECTIONS }).notNull(),
  sortOrder: integer("sort_order").notNull().default(0),
  archivedAt: integer("archived_at"),
  createdAt: createdAt(),
});

export const customFieldValues = sqliteTable(
  "custom_field_values",
  {
    id: id(),
    fieldId: text("field_id")
      .notNull()
      .references(() => customFieldDefs.id, { onDelete: "cascade" }),
    entityType: text("entity_type", { enum: CUSTOM_FIELD_SCOPES }).notNull(),
    /** Workspace values use entity ID "workspace". */
    entityId: text("entity_id").notNull(),
    value: text("value").notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("custom_field_values_field_entity_uq").on(t.fieldId, t.entityType, t.entityId),
    index("custom_field_values_entity_idx").on(t.entityType, t.entityId),
  ],
);

// ---------------------------------------------------------------------------
// Clients
// ---------------------------------------------------------------------------

export const clients = sqliteTable(
  "clients",
  {
    id: id(),
    name: text("name").notNull(),
    billingAddress: text("billing_address"),
    taxId: text("tax_id"),
    defaultCurrency: text("default_currency").notNull().default("BDT"),
    defaultTaxRateId: text("default_tax_rate_id").references(() => taxRates.id, {
      onDelete: "set null",
    }),
    /** Null means the workspace default. */
    paymentTermsDays: integer("payment_terms_days"),
    templateId: text("template_id").references(() => templates.id, { onDelete: "set null" }),
    reminderMode: text("reminder_mode", { enum: REMINDER_MODE_SETTINGS })
      .notNull()
      .default("inherit"),
    recurringSendMode: text("recurring_send_mode", { enum: SEND_MODE_SETTINGS })
      .notNull()
      .default("inherit"),
    notes: text("notes"),
    archivedAt: integer("archived_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("clients_name_idx").on(t.name), index("clients_archived_idx").on(t.archivedAt)],
);

export const clientContacts = sqliteTable(
  "client_contacts",
  {
    id: id(),
    clientId: text("client_id")
      .notNull()
      .references(() => clients.id, { onDelete: "cascade" }),
    name: text("name"),
    email: text("email").notNull(),
    isPrimary: bool("is_primary").notNull().default(false),
    /** Billing contacts receive documents and reminders with the primary contact. */
    isBilling: bool("is_billing").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [
    index("client_contacts_client_idx").on(t.clientId),
    uniqueIndex("client_contacts_one_primary_uq").on(t.clientId).where(sql`is_primary = 1`),
  ],
);

// ---------------------------------------------------------------------------
// Documents (quotes and invoices)
// ---------------------------------------------------------------------------

/**
 * Quotes and invoices. Drafts are live rows. Sent documents render only from
 * `document_revisions.snapshot`. Cached totals here serve lists and filters.
 */
export const documents = sqliteTable(
  "documents",
  {
    id: id(),
    kind: text("kind", { enum: DOCUMENT_KINDS }).notNull(),
    status: text("status", { enum: DOCUMENT_STATUSES }).notNull().default("draft"),
    /** Allocated once at first send, for example "INV-0042". */
    number: text("number"),
    clientId: text("client_id")
      .notNull()
      .references(() => clients.id),
    currency: text("currency").notNull(),
    issueDate: text("issue_date"),
    /** Invoices only. */
    dueDate: text("due_date"),
    /** Quotes only. */
    expiryDate: text("expiry_date"),
    paymentTermsDays: integer("payment_terms_days"),
    discountType: text("discount_type", { enum: DISCOUNT_TYPES }).notNull().default("none"),
    /** Percent as a decimal string when discount_type is "percent". */
    discountPercent: text("discount_percent"),
    /** Minor units when discount_type is "fixed". */
    discountAmount: integer("discount_amount"),
    notes: text("notes"),
    footerText: text("footer_text"),
    templateId: text("template_id").references(() => templates.id, { onDelete: "set null" }),
    reminderMode: text("reminder_mode", { enum: REMINDER_MODE_SETTINGS })
      .notNull()
      .default("inherit"),
    // Exchange rate to the home currency (one document unit = rate home units).
    fxRate: text("fx_rate"),
    fxRateScaled: integer("fx_rate_scaled"),
    fxRateDate: text("fx_rate_date"),
    fxProvider: text("fx_provider", { enum: FX_PROVIDERS }),
    fxOverridden: bool("fx_overridden").notNull().default(false),
    /** 128-bit random base64url token for the public link. */
    publicToken: text("public_token").unique(),
    currentRevisionId: text("current_revision_id"),
    revisionCount: integer("revision_count").notNull().default(0),
    // Cached document-currency totals (from the money engine).
    subtotal: integer("subtotal").notNull().default(0),
    discountTotal: integer("discount_total").notNull().default(0),
    taxTotal: integer("tax_total").notNull().default(0),
    total: integer("total").notNull().default(0),
    /** Sum of payments and write-offs. Balance = total - amount_paid. */
    amountPaid: integer("amount_paid").notNull().default(0),
    /** Scheduler cache of the derived overdue state, for list filters. */
    isOverdue: bool("is_overdue").notNull().default(false),
    // Links between documents. No foreign keys, so batches can write them in any order.
    sourceQuoteId: text("source_quote_id"),
    convertedInvoiceId: text("converted_invoice_id"),
    recurringScheduleId: text("recurring_schedule_id"),
    /** Billing period that created this invoice, for example "2026-10". */
    recurringPeriodId: text("recurring_period_id"),
    // Quote decision
    decidedAt: integer("decided_at"),
    decisionComment: text("decision_comment"),
    finalizedAt: integer("finalized_at"),
    sentAt: integer("sent_at"),
    paidAt: integer("paid_at"),
    voidedAt: integer("voided_at"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check(
      "documents_status_kind",
      sql`(kind = 'invoice' and status in (${inList(INVOICE_STATUSES)})) or (kind = 'quote' and status in (${inList(QUOTE_STATUSES)}))`,
    ),
    uniqueIndex("documents_kind_number_uq").on(t.kind, t.number),
    uniqueIndex("documents_recurring_period_uq").on(t.recurringScheduleId, t.recurringPeriodId),
    // Status filters, and due-date ranges on open invoices (overdue tick, dashboard, aging).
    index("documents_kind_status_due_idx").on(t.kind, t.status, t.dueDate),
    // The list pages: one kind, newest first, so a page reads only its own rows.
    index("documents_kind_updated_idx").on(t.kind, t.updatedAt, t.id),
    // The few invoices flagged overdue, so the tick can clear the flag without a scan.
    index("documents_overdue_idx").on(t.kind, t.isOverdue).where(sql`is_overdue = 1`),
    // Client detail: the client's documents, newest first. Also serves the foreign key.
    index("documents_client_created_idx").on(t.clientId, t.createdAt),
  ],
);

export const documentLines = sqliteTable(
  "document_lines",
  {
    id: id(),
    documentId: text("document_id")
      .notNull()
      .references(() => documents.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    description: text("description").notNull().default(""),
    quantity: text("quantity").notNull().default("1"),
    unitPrice: integer("unit_price").notNull().default(0),
    taxRateId: text("tax_rate_id").references(() => taxRates.id, { onDelete: "set null" }),
  },
  (t) => [index("document_lines_document_idx").on(t.documentId, t.position)],
);

/** Snapshot JSON as written at send or revise. U8 owns its exact shape. */
export type RevisionSnapshot = Record<string, unknown>;

/** A frozen version of a sent document, with report columns. */
export const documentRevisions = sqliteTable(
  "document_revisions",
  {
    id: id(),
    documentId: text("document_id")
      .notNull()
      .references(() => documents.id, { onDelete: "cascade" }),
    revisionNumber: integer("revision_number").notNull(),
    snapshot: text("snapshot", { mode: "json" }).$type<RevisionSnapshot>().notNull(),
    /** R2 key of the cached PDF, for example "pdfs/<revisionId>.pdf". */
    pdfKey: text("pdf_key"),
    kind: text("kind", { enum: DOCUMENT_KINDS }).notNull(),
    status: text("status", { enum: DOCUMENT_STATUSES }).notNull(),
    clientId: text("client_id").notNull(),
    issueDate: text("issue_date").notNull(),
    dueDate: text("due_date"),
    currency: text("currency").notNull(),
    subtotal: integer("subtotal").notNull(),
    discountTotal: integer("discount_total").notNull(),
    taxTotal: integer("tax_total").notNull(),
    total: integer("total").notNull(),
    homeCurrency: text("home_currency").notNull(),
    fxRate: text("fx_rate").notNull(),
    homeSubtotal: integer("home_subtotal").notNull(),
    homeDiscountTotal: integer("home_discount_total").notNull(),
    homeTaxTotal: integer("home_tax_total").notNull(),
    homeTotal: integer("home_total").notNull(),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("document_revisions_doc_number_uq").on(t.documentId, t.revisionNumber),
    index("document_revisions_issue_date_idx").on(t.issueDate),
  ],
);

/** One row per tax rate per revision, so reports aggregate in SQL. */
export const revisionTaxTotals = sqliteTable(
  "revision_tax_totals",
  {
    revisionId: text("revision_id")
      .notNull()
      .references(() => documentRevisions.id, { onDelete: "cascade" }),
    taxRateId: text("tax_rate_id").notNull(),
    documentId: text("document_id").notNull(),
    issueDate: text("issue_date").notNull(),
    name: text("name").notNull(),
    rate: text("rate").notNull(),
    taxable: integer("taxable").notNull(),
    tax: integer("tax").notNull(),
    homeTaxable: integer("home_taxable").notNull(),
    homeTax: integer("home_tax").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.revisionId, t.taxRateId] }),
    index("revision_tax_totals_issue_date_idx").on(t.issueDate, t.taxRateId),
  ],
);

export const payments = sqliteTable(
  "payments",
  {
    id: id(),
    documentId: text("document_id")
      .notNull()
      .references(() => documents.id, { onDelete: "cascade" }),
    /** "write_off" records the remainder written off when marking paid. */
    kind: text("kind", { enum: PAYMENT_KINDS }).notNull().default("payment"),
    /** Minor units in the invoice currency. */
    amount: integer("amount").notNull(),
    /** Converted at the invoice's stored rate. */
    homeAmount: integer("home_amount").notNull(),
    paidOn: text("paid_on").notNull(),
    note: text("note"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  (t) => [
    index("payments_document_idx").on(t.documentId),
    index("payments_paid_on_idx").on(t.paidOn),
    check("payments_amount_positive", sql`amount > 0`),
  ],
);

// ---------------------------------------------------------------------------
// Recurring schedules
// ---------------------------------------------------------------------------

export const recurringSchedules = sqliteTable(
  "recurring_schedules",
  {
    id: id(),
    clientId: text("client_id")
      .notNull()
      .references(() => clients.id),
    sourceDocumentId: text("source_document_id"),
    name: text("name"),
    currency: text("currency").notNull(),
    frequency: text("frequency", { enum: RECURRING_FREQUENCIES }).notNull(),
    startDate: text("start_date").notNull(),
    endDate: text("end_date"),
    /** Day of month the schedule is anchored on (29 to 31 fall back to month end). */
    anchorDay: integer("anchor_day").notNull(),
    /** Period cursor: the next issue date to create. */
    nextIssueDate: text("next_issue_date").notNull(),
    /** The last billing period created, for example "2026-10". */
    lastPeriodId: text("last_period_id"),
    sendMode: text("send_mode", { enum: SEND_MODE_SETTINGS }).notNull().default("inherit"),
    status: text("status", { enum: RECURRING_STATUSES }).notNull().default("active"),
    pausedReason: text("paused_reason"),
    paymentTermsDays: integer("payment_terms_days"),
    templateId: text("template_id").references(() => templates.id, { onDelete: "set null" }),
    discountType: text("discount_type", { enum: DISCOUNT_TYPES }).notNull().default("none"),
    discountPercent: text("discount_percent"),
    discountAmount: integer("discount_amount"),
    notes: text("notes"),
    footerText: text("footer_text"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("recurring_schedules_due_idx").on(t.status, t.nextIssueDate),
    index("recurring_schedules_client_idx").on(t.clientId),
  ],
);

/** The schedule's own copy of the line items. */
export const recurringScheduleLines = sqliteTable(
  "recurring_schedule_lines",
  {
    id: id(),
    scheduleId: text("schedule_id")
      .notNull()
      .references(() => recurringSchedules.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    description: text("description").notNull().default(""),
    quantity: text("quantity").notNull().default("1"),
    unitPrice: integer("unit_price").notNull().default(0),
    taxRateId: text("tax_rate_id").references(() => taxRates.id, { onDelete: "set null" }),
  },
  (t) => [index("recurring_schedule_lines_schedule_idx").on(t.scheduleId, t.position)],
);

// ---------------------------------------------------------------------------
// Scheduler, numbering, email, activity, and caches
// ---------------------------------------------------------------------------

/** Job outbox. `idempotency_key` makes each recurring period and reminder step run once. */
export const jobs = sqliteTable(
  "jobs",
  {
    id: id(),
    type: text("type").notNull(),
    payload: text("payload", { mode: "json" }).$type<unknown>().notNull().default({}),
    idempotencyKey: text("idempotency_key").notNull().unique(),
    status: text("status", { enum: JOB_STATUSES }).notNull().default("pending"),
    attempts: integer("attempts").notNull().default(0),
    maxAttempts: integer("max_attempts").notNull().default(3),
    runAfter: integer("run_after").notNull().default(nowMs),
    /** A claimed job is leased until this time. An expired lease can be claimed again. */
    leaseUntil: integer("lease_until"),
    leaseOwner: text("lease_owner"),
    lastError: text("last_error"),
    finishedAt: integer("finished_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("jobs_status_run_after_idx").on(t.status, t.runAfter)],
);

/** Number sequences: "invoice" and "quote". */
export const counters = sqliteTable("counters", {
  name: text("name").primaryKey(),
  value: integer("value").notNull().default(0),
});

/** Every email the app tried to send. Counts per day enforce the Resend daily cap. */
export const emailLog = sqliteTable(
  "email_log",
  {
    id: id(),
    /** Workspace-timezone date of the send, for the daily count. */
    day: text("day").notNull(),
    kind: text("kind", { enum: EMAIL_KINDS }).notNull(),
    trigger: text("trigger", { enum: TRIGGERS }).notNull().default("manual"),
    documentId: text("document_id").references(() => documents.id, { onDelete: "set null" }),
    revisionId: text("revision_id"),
    /** Reminder step offset in days from the due date. Null for other kinds. */
    reminderOffsetDays: integer("reminder_offset_days"),
    recipients: text("recipients", { mode: "json" }).$type<string[]>().notNull(),
    subject: text("subject").notNull(),
    status: text("status", { enum: EMAIL_STATUSES }).notNull(),
    providerId: text("provider_id"),
    error: text("error"),
    createdAt: createdAt(),
  },
  (t) => [
    index("email_log_day_idx").on(t.day, t.status),
    index("email_log_document_idx").on(t.documentId, t.kind, t.createdAt),
    index("email_log_provider_idx").on(t.providerId),
  ],
);

/** Document and client history: created, sent, viewed, reminded, paid, voided, and more. */
export const activity = sqliteTable(
  "activity",
  {
    id: id(),
    documentId: text("document_id").references(() => documents.id, { onDelete: "cascade" }),
    clientId: text("client_id").references(() => clients.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    actorUserId: text("actor_user_id").references(() => users.id, { onDelete: "set null" }),
    data: text("data", { mode: "json" }).$type<Record<string, unknown>>(),
    createdAt: createdAt(),
  },
  (t) => [index("activity_document_idx").on(t.documentId, t.createdAt)],
);

/** In-app owner notifications (dashboard list). */
export const notifications = sqliteTable(
  "notifications",
  {
    id: id(),
    type: text("type").notNull(),
    title: text("title").notNull(),
    body: text("body"),
    documentId: text("document_id").references(() => documents.id, { onDelete: "cascade" }),
    readAt: integer("read_at"),
    createdAt: createdAt(),
  },
  (t) => [index("notifications_read_idx").on(t.readAt, t.createdAt)],
);

/** Exchange rate cache, keyed by the requested date. */
export const fxRates = sqliteTable(
  "fx_rates",
  {
    base: text("base").notNull(),
    quote: text("quote").notNull(),
    requestedDate: text("requested_date").notNull(),
    /** The provider's effective date (the latest business day on or before the request). */
    rateDate: text("rate_date").notNull(),
    rate: text("rate").notNull(),
    rateScaled: integer("rate_scaled").notNull(),
    provider: text("provider", { enum: FX_PROVIDERS }).notNull(),
    fetchedAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.base, t.quote, t.requestedDate] })],
);

/** Named leases, for example "browser" to space PDF renders 10 s apart. */
export const leases = sqliteTable("leases", {
  name: text("name").primaryKey(),
  holder: text("holder"),
  expiresAt: integer("expires_at").notNull().default(0),
  lastUsedAt: integer("last_used_at"),
});

// ---------------------------------------------------------------------------
// Inferred types
// ---------------------------------------------------------------------------

export type Workspace = typeof workspace.$inferSelect;
export type NewWorkspace = typeof workspace.$inferInsert;
export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type TaxRate = typeof taxRates.$inferSelect;
export type NewTaxRate = typeof taxRates.$inferInsert;
export type Template = typeof templates.$inferSelect;
export type NewTemplate = typeof templates.$inferInsert;
export type CustomFieldDef = typeof customFieldDefs.$inferSelect;
export type NewCustomFieldDef = typeof customFieldDefs.$inferInsert;
export type CustomFieldValue = typeof customFieldValues.$inferSelect;
export type NewCustomFieldValue = typeof customFieldValues.$inferInsert;
export type Client = typeof clients.$inferSelect;
export type NewClient = typeof clients.$inferInsert;
export type ClientContact = typeof clientContacts.$inferSelect;
